+// ─── S117 ROOT-065 (UTF-16 unit count law) ───────────────────────────────
+// OpenJDK/AOSP String.length() answers the number of UTF-16 code units,
+// NOT the number of bytes in any particular encoding. The engine's internal
+// string representation is UTF-8, where units occupy 1..4 bytes — so
+// `string_val.size()` over-reports length for every string containing a
+// multi-byte character. Evidence (official Telegram, play_billing
+// protobuf-lite schema decode): the RawMessageInfo template string packs
+// 13-bit digits into chars (including U+0000 encoded as MUTF-8 0xC0 0x80
+// and 0x1000-block digit markers); the schema parser loops over
+// String.length()/charAt() and a BYTE-count length made it parse 15+ extra
+// phantom "field entries" past the real string end → objects[11] read on
+// an 11-element array → ArrayIndexOutOfBoundsException →
+// BillingController.<init> → LaunchActivity.onCreate APP-BOUNDARY death.
+// LAW: count code points by walking UTF-8 lead bytes, and count each
+// supplementary code point (≥ U+10000, 4-byte sequence) as TWO units —
+// exactly the UTF-16 storage a JVM String uses. ASCII-only strings (the
+// corpus majority) are unaffected: byte count == unit count there.
+static int32_t utf16_unit_count(const std::string& utf8) {
+    int32_t units = 0;
+    for (size_t i = 0; i < utf8.size();) {
+        const unsigned char b = static_cast<unsigned char>(utf8[i]);
+        if (b < 0x80) {
+            i += 1;
+        } else if ((b & 0xE0) == 0xC0) {
+            i += 2;
+        } else if ((b & 0xF0) == 0xE0) {
+            i += 3;
+        } else if ((b & 0xF8) == 0xF0) {
+            i += 4;
+            ++units;  // a supplementary code point occupies TWO UTF-16 units
+        } else {
+            i += 1;  // malformed lead — advance one byte (defensive)
+        }
+        ++units;
+    }
+    return units;
+}
